import{_ as a,o as n,c as r,a5 as o}from"./chunks/framework.Cooo9kuv.js";const g=JSON.parse('{"title":"WordPress 搜索引擎主动推送插件 — Bing & IndexNow Push","description":"","frontmatter":{"标题":"WordPress 搜索引擎主动推送插件 — Bing & IndexNow Push","日期":"2026-07-12T00:00:00.000Z","修改日期":"2026-07-13T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["wordpress主题插件"],"标签":["Bing推送","IndexNow","SEO优化","URL主动提交","WordPress","搜索引擎推送","搜索引擎收录","网站索引"]},"headers":[{"level":2,"title":"插件简介","slug":"插件简介","link":"#插件简介","children":[]},{"level":2,"title":"功能特性","slug":"功能特性","link":"#功能特性","children":[{"level":3,"title":"双通道独立推送","slug":"双通道独立推送","link":"#双通道独立推送","children":[]},{"level":3,"title":"三种推送触发方式","slug":"三种推送触发方式","link":"#三种推送触发方式","children":[]},{"level":3,"title":"智能去重与轮次管理","slug":"智能去重与轮次管理","link":"#智能去重与轮次管理","children":[]},{"level":3,"title":"外部 API 远程调用","slug":"外部-api-远程调用","link":"#外部-api-远程调用","children":[]},{"level":3,"title":"IndexNow Key 自动管理","slug":"indexnow-key-自动管理","link":"#indexnow-key-自动管理","children":[]},{"level":3,"title":"全量推送日志","slug":"全量推送日志","link":"#全量推送日志","children":[]},{"level":3,"title":"中英双语界面","slug":"中英双语界面","link":"#中英双语界面","children":[]}]},{"level":2,"title":"使用说明","slug":"使用说明","link":"#使用说明","children":[{"level":3,"title":"第一步：安装插件","slug":"第一步-安装插件","link":"#第一步-安装插件","children":[]},{"level":3,"title":"第二步：配置 Bing 推送","slug":"第二步-配置-bing-推送","link":"#第二步-配置-bing-推送","children":[]},{"level":3,"title":"第三步：配置 IndexNow 推送","slug":"第三步-配置-indexnow-推送","link":"#第三步-配置-indexnow-推送","children":[]},{"level":3,"title":"第四步：验证生效","slug":"第四步-验证生效","link":"#第四步-验证生效","children":[]}]},{"level":2,"title":"注意事项","slug":"注意事项","link":"#注意事项","children":[]},{"level":2,"title":"反馈与支持","slug":"反馈与支持","link":"#反馈与支持","children":[]},{"level":2,"title":"更新日志","slug":"更新日志","link":"#更新日志","children":[{"level":3,"title":"v1.0.0（2026-06）","slug":"v1-0-0-2026-06","link":"#v1-0-0-2026-06","children":[]}]}],"relativePath":"md/wordpress主题插件/WordPress 搜索引擎主动推送插件 — Bing & IndexNow Push.md","filePath":"md/wordpress主题插件/WordPress 搜索引擎主动推送插件 — Bing & IndexNow Push.md"}'),l={name:"md/wordpress主题插件/WordPress 搜索引擎主动推送插件 — Bing & IndexNow Push.md"};function t(i,e,s,d,h,p){return n(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="wordpress-搜索引擎主动推送插件-—-bing-indexnow-push" tabindex="-1">WordPress 搜索引擎主动推送插件 — Bing &amp; IndexNow Push <a class="header-anchor" href="#wordpress-搜索引擎主动推送插件-—-bing-indexnow-push" aria-label="Permalink to &quot;WordPress 搜索引擎主动推送插件 — Bing &amp; IndexNow Push&quot;">​</a></h1><blockquote><p>自动将 WordPress 文章与页面的 URL 提交至 Bing Webmaster API 和 IndexNow 协议，帮助搜索引擎即时发现并收录网站内容，提升搜索索引速度与覆盖率。</p></blockquote><p><strong>版本</strong>：v1.0.0<br><strong>适配</strong>：WordPress 5.8+<br><strong>PHP</strong>：&gt;= 7.2<br><strong>作者</strong>：softbangong<br><strong>授权</strong>：不限制网站数量，下载安装后永久免费使用</p><h2 id="插件简介" tabindex="-1">插件简介 <a class="header-anchor" href="#插件简介" aria-label="Permalink to &quot;插件简介&quot;">​</a></h2><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/4110675e-9490-403f-bd4f-7b3e5ce0a2e6.png" alt=""></p><p>本插件用于将 WordPress 网站的文章和页面 URL 主动推送至搜索引擎，支持两条推送通道：</p><p>— Bing 通道：通过 Bing Webmaster Tools API 提交 URL，让 Bing 搜索引擎第一时间发现新内容；<br> — IndexNow 通道：通过 IndexNow 协议提交 URL，同时被 Bing、Yandex、Seznam 等多个搜索引擎接收。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/38e77840-da19-4544-bc65-09eb53fc147d.png" alt=""></p><p>插件在后台提供集中化的配置管理界面，Bing 和 IndexNow 两个通道独立设置、独立统计，支持自动推送、手动推送、发布即推送三种触发方式，并记录每次推送的详细日志方便排查。</p><h2 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to &quot;功能特性&quot;">​</a></h2><h3 id="双通道独立推送" tabindex="-1">双通道独立推送 <a class="header-anchor" href="#双通道独立推送" aria-label="Permalink to &quot;双通道独立推送&quot;">​</a></h3><p>插件提供 Bing 和 IndexNow 两条推送通道，各自拥有独立的 API Key、推送间隔、批量上限和启用开关，可按需单独启用或同时开启，互不干扰。</p><h3 id="三种推送触发方式" tabindex="-1">三种推送触发方式 <a class="header-anchor" href="#三种推送触发方式" aria-label="Permalink to &quot;三种推送触发方式&quot;">​</a></h3><p>— 发布即推送：文章或页面发布、更新时自动触发推送，无需等待定时任务；<br> — 定时批量推送：前端页面被访问时按配置的间隔自动检查并推送未提交的 URL，对已推送过的 URL 自动去重避免重复提交；<br> — 手动立即推送：后台点击推送按钮即时执行，适用于批量补推或紧急发布场景。</p><h3 id="智能去重与轮次管理" tabindex="-1">智能去重与轮次管理 <a class="header-anchor" href="#智能去重与轮次管理" aria-label="Permalink to &quot;智能去重与轮次管理&quot;">​</a></h3><p>插件通过文章自定义字段记录每条 URL 的推送状态，已推送的 URL 不会重复提交。当所有文章均已推送一轮后，自动清除标记重新开始新一轮推送，确保新增或修改的文章不会遗漏。</p><h3 id="外部-api-远程调用" tabindex="-1">外部 API 远程调用 <a class="header-anchor" href="#外部-api-远程调用" aria-label="Permalink to &quot;外部 API 远程调用&quot;">​</a></h3><p>配置外部调用密钥后，可通过 HTTP GET 请求远程触发 Bing 推送：</p><p>— 调用地址：<code>https://your-site.com/wp-content/plugins/bing_push/bing_api.php?key=YOUR_KEY</code></p><p>适用于第三方监控系统、外部定时任务或 CI/CD 流水线集成。</p><h3 id="indexnow-key-自动管理" tabindex="-1">IndexNow Key 自动管理 <a class="header-anchor" href="#indexnow-key-自动管理" aria-label="Permalink to &quot;IndexNow Key 自动管理&quot;">​</a></h3><p>— 支持一键随机生成 IndexNow Key（基于浏览器 Crypto API 生成 32 位十六进制字符串）；<br> — 保存配置后自动在网站根目录创建 Key 验证文件（如 <code>your-key.txt</code>），满足 IndexNow 协议的域名验证要求；<br> — 更换 Key 时自动清理旧的验证文件，保持网站根目录整洁。</p><h3 id="全量推送日志" tabindex="-1">全量推送日志 <a class="header-anchor" href="#全量推送日志" aria-label="Permalink to &quot;全量推送日志&quot;">​</a></h3><p>后台提供按通道独立过滤的推送日志面板：</p><p>— 记录每次推送的时间、触发类型（手动 / 自动 / 发布触发）、URL 数量、成功/失败状态、API 响应详情；<br> — 保留最近 50 条日志记录，支持按通道单独清除或全部清除。</p><h3 id="中英双语界面" tabindex="-1">中英双语界面 <a class="header-anchor" href="#中英双语界面" aria-label="Permalink to &quot;中英双语界面&quot;">​</a></h3><p>插件内置中文、英文及自动（跟随系统语言）三种语言模式，后台顶部提供语言切换选择器即时生效。</p><h2 id="使用说明" tabindex="-1">使用说明 <a class="header-anchor" href="#使用说明" aria-label="Permalink to &quot;使用说明&quot;">​</a></h2><h3 id="第一步-安装插件" tabindex="-1">第一步：安装插件 <a class="header-anchor" href="#第一步-安装插件" aria-label="Permalink to &quot;第一步：安装插件&quot;">​</a></h3><p>将 <code>bing_push</code> 文件夹上传至网站 <code>wp-content/plugins/</code> 目录，进入 WordPress 后台「插件」页面，找到「Bing &amp; IndexNow Push」并点击启用。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/image-22.png" alt=""></p><h3 id="第二步-配置-bing-推送" tabindex="-1">第二步：配置 Bing 推送 <a class="header-anchor" href="#第二步-配置-bing-推送" aria-label="Permalink to &quot;第二步：配置 Bing 推送&quot;">​</a></h3><p>进入后台「Bing/IndexNow」菜单，在「Bing 推送」Tab 下：</p><p>— 填入从 Bing Webmaster Tools 获取的 API Key；<br> — 设置自动推送间隔（默认 5 分钟，范围 1-1440 分钟）和每批推送上限（默认 10 条）；<br> — 设置外部调用密钥（可选），用于远程触发推送；<br> — 勾选「启用自动推送」以开启定时提交；<br> — 点击「保存设置」。</p><p>确认配置无误后，可点击「立即推送」按钮手动触发一次推送以验证通道是否通畅。</p><h3 id="第三步-配置-indexnow-推送" tabindex="-1">第三步：配置 IndexNow 推送 <a class="header-anchor" href="#第三步-配置-indexnow-推送" aria-label="Permalink to &quot;第三步：配置 IndexNow 推送&quot;">​</a></h3><p>切换到「IndexNow」Tab：</p><p>— 生成或手动输入 IndexNow Key（建议使用随机生成按钮一键创建）；<br> — 保存后插件会自动在网站根目录创建 <code>{key}.txt</code> 验证文件；<br> — 设置推送间隔和批量上限，勾选「启用自动推送」；<br> — 点击「保存设置」。</p><h3 id="第四步-验证生效" tabindex="-1">第四步：验证生效 <a class="header-anchor" href="#第四步-验证生效" aria-label="Permalink to &quot;第四步：验证生效&quot;">​</a></h3><p>— 发布一篇新文章或页面，推送日志中应出现「发布触发」类型的记录；<br> — 访问网站前台任意页面，等待推送间隔到期后检查日志是否出现「自动」类型的推送记录；<br> — 使用外部调用地址测试远程触发功能。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>— 使用 Bing 推送前需先在 Bing Webmaster Tools 中完成网站所有权验证并获取 API Key；<br> — IndexNow 推送依赖网站根目录的 Key 验证文件，请确保 Web 服务器允许写入 WordPress 根目录；如果写入失败需手动创建；<br> — 自动推送依赖前端页面访问触发，纯后台操作不会触发定时推送；如需更强的定时可靠性，建议配合系统 Cron 调用外部 API 地址；<br> — 推送日志仅保留最近 50 条，重要数据请定期备份；<br> — Bing 推送和 IndexNow 推送均有 API 调用频率限制，请根据网站文章量合理设置推送间隔。</p><h2 id="反馈与支持" tabindex="-1">反馈与支持 <a class="header-anchor" href="#反馈与支持" aria-label="Permalink to &quot;反馈与支持&quot;">​</a></h2><p>— 作者：softbangong<br> — 作者网站：softbangong.com<br> — 作者网站：softbangong.top<br> — 邮箱：<a href="mailto:yunjuliangpin@163.com" target="_blank" rel="noreferrer">yunjuliangpin@163.com</a><br> — 邮箱：<a href="mailto:softbangong@gmail.com" target="_blank" rel="noreferrer">softbangong@gmail.com</a></p><h2 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to &quot;更新日志&quot;">​</a></h2><h3 id="v1-0-0-2026-06" tabindex="-1">v1.0.0（2026-06） <a class="header-anchor" href="#v1-0-0-2026-06" aria-label="Permalink to &quot;v1.0.0（2026-06）&quot;">​</a></h3><p>— 首发版本，支持 Bing Webmaster API 和 IndexNow 协议双通道 URL 推送；<br> — 发布/更新自动触发推送，定时批量推送，手动立即推送三种触发方式；<br> — 基于文章自定义字段的推送去重与轮次自动重置机制；<br> — 外部 API 远程调用接口，支持密钥鉴权；<br> — IndexNow Key 随机生成与验证文件自动管理；<br> — 双通道独立统计数据面板（累计推送量、上次状态、上次数量）；<br> — 推送日志记录与按通道清除功能；<br> — 中英双语界面（中文 / English / 自动跟随系统语言）。</p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/3014.html" target="_blank" rel="noreferrer">https://www.softbangong.com/3014.html</a></p>',49)])])}const c=a(l,[["render",t]]);export{g as __pageData,c as default};
